package br.com.shirokaidex.config;
import br.com.shirokaidex.menus.direct.MenuSpec;
import com.google.gson.*;
import com.google.gson.stream.JsonReader;
import java.io.*;
import java.nio.file.*;
import java.util.*;

/** One immutable snapshot of the separately editable supported public menus. No player import. */
public record DirectMenuCatalog(Map<String,MenuSpec> menus,Map<String,List<RewardDisplay>> displays,Map<String,String> messages,Map<String,String> rawFiles){
    private static final Set<String> MESSAGE_KEYS=Set.of("search_prompt","search_cancelled","search_expired","loading","no_data","claimed","unavailable");
    public static final List<String> FILES=List.of("dex_nacional","dex_special","dex_shiny","dex_forms","wiki_nacional","wiki_special","wiki_shiny","wiki_forms","rank_captura","rank_derrotados","rank_dex","messages");
    public record RewardDisplay(String id,String name,String icon,List<String> lore){public RewardDisplay{lore=List.copyOf(lore);br.com.shirokaidex.pokedex.CollectionDefinition.identifier(icon);}}
    public DirectMenuCatalog {menus=Map.copyOf(menus);var d=new HashMap<String,List<RewardDisplay>>();displays.forEach((k,v)->d.put(k,List.copyOf(v)));displays=Map.copyOf(d);messages=Map.copyOf(messages);rawFiles=Map.copyOf(rawFiles);}
    public static String collection(String name){return switch(name){case "nacional","national"->"national";case "special"->"special";case "shiny"->"shiny";case "forms"->"forms";default->null;};}
    public static String command(String id){return id.equals("national")?"nacional":id;}
    public static void initialize(Path directory)throws IOException {var path=directory.resolve("menus");Files.createDirectories(path);for(String file:FILES){var target=path.resolve(file+".json");if(Files.notExists(target)){try(var input=DirectMenuCatalog.class.getResourceAsStream("/config/menus/"+file+".json")){if(input==null)throw new IOException("Missing menu preset "+file);Files.write(target,input.readAllBytes(),StandardOpenOption.CREATE_NEW);}}}}
    public static DirectMenuCatalog load(Path directory)throws IOException{var files=new LinkedHashMap<String,String>();for(String file:FILES){byte[] bytes;try(var in=Files.newInputStream(directory.resolve("menus/"+file+".json"))){bytes=in.readNBytes(131073);}if(bytes.length>131072)throw new IOException("Menu file too large: "+file);try{files.put(file,java.nio.charset.StandardCharsets.UTF_8.newDecoder().decode(java.nio.ByteBuffer.wrap(bytes)).toString());}catch(java.nio.charset.CharacterCodingException invalid){throw new IOException("Invalid UTF-8 menu: "+file,invalid);}}return parse(files);}
    public static DirectMenuCatalog parse(Map<String,String> files)throws IOException {
        var menus=new HashMap<String,MenuSpec>();var displays=new HashMap<String,List<RewardDisplay>>();var messages=new HashMap<String,String>();
        try{for(String file:FILES){var object=object(files.get(file));if(file.equals("messages")){if(!object.keySet().equals(MESSAGE_KEYS))throw new IllegalArgumentException("Missing or unknown direct menu message");for(var e:object.entrySet()){String text=string(e.getValue());br.com.shirokaidex.menus.direct.RichText.validate(text);messages.put(e.getKey(),text);}continue;}
            if(file.startsWith("dex_")&&!file.equals("dex_forms")){keys(object,Set.of("collection","menu","reward_groups"));var groups=new ArrayList<RewardDisplay>();var ids=new HashSet<String>();for(var value:object.getAsJsonArray("reward_groups")){var g=value.getAsJsonObject();keys(g,Set.of("id","percent","name","icon","lore","items","currencies","permissions"));String id=string(g.get("id"));if(!ids.add(id))throw new IllegalArgumentException("Duplicate reward display");br.com.shirokaidex.menus.direct.RichText.validate(string(g.get("name")));for(String line:strings(g.getAsJsonArray("lore")))br.com.shirokaidex.menus.direct.RichText.validate(line);groups.add(new RewardDisplay(id,string(g.get("name")),string(g.get("icon")),strings(g.getAsJsonArray("lore"))));}displays.put(file,List.copyOf(groups));var spec=menu(object.getAsJsonObject("menu"),file);for(var group:groups)for(var style:spec.rewardStates().values()){var combined=new ArrayList<String>(group.lore());combined.addAll(style.lore());new MenuSpec.Icon(style.item(),style.name().replace("%group_name%",group.name()),combined,style.glint());}menus.put(file,spec);}
            else menus.put(file,menu(object,file));
        }}catch(RuntimeException e){throw new IOException("Invalid direct menu configuration",e);}return new DirectMenuCatalog(menus,displays,messages,files);
    }
    public String effective(String original)throws IOException {
        var root=object(original);var defaults=object(resource("/config/focused.json"));
        var categories=root.has("categories")?root.getAsJsonArray("categories"):new JsonArray();var known=new HashSet<String>();for(var v:categories)known.add(v.getAsJsonObject().get("id").getAsString());for(var v:defaults.getAsJsonArray("categories"))if(known.add(v.getAsJsonObject().get("id").getAsString()))categories.add(v);root.add("categories",categories);
        var collections=new JsonArray();var rewards=new JsonArray();for(String cmd:List.of("nacional","special","shiny")){var raw=object(rawFiles.get("dex_"+cmd));collections.add(raw.get("collection"));for(var value:raw.getAsJsonArray("reward_groups")){var g=value.getAsJsonObject();var plan=new JsonObject();plan.add("id",g.get("id"));plan.addProperty("collection",collection(cmd));plan.add("minimum_percent",g.get("percent"));for(String field:List.of("items","currencies","permissions"))if(g.has(field))plan.add(field,g.get(field));rewards.add(plan);}}
        root.add("collections",collections);root.add("rewards",rewards);root.add("rankings",defaults.get("rankings"));root.add("competitions",new JsonArray());root.add("achievements",new JsonArray());root.add("menus",new JsonObject());root.add("home",defaults.get("home"));return root.toString();
    }
    public static JsonObject object(String json)throws IOException{if(json==null)throw new IOException("Missing menu file");try(var reader=new JsonReader(new StringReader(json))){reader.setLenient(false);var result=StrictJson.object(reader);if(reader.peek()!=com.google.gson.stream.JsonToken.END_DOCUMENT)throw new IOException("Trailing menu JSON");return result;}}
    private static String resource(String path)throws IOException{try(var input=DirectMenuCatalog.class.getResourceAsStream(path)){if(input==null)throw new IOException("Missing resource");return new String(input.readAllBytes(),java.nio.charset.StandardCharsets.UTF_8);}}
    private static MenuSpec menu(JsonObject o,String id){keys(o,Set.of("title","rows","background","buttons","content_slots","reward_slots","reward_states","entry","ranking_line","filter_names"));var buttons=new LinkedHashMap<String,MenuSpec.Button>();Set<String> allowed=id.startsWith("wiki_")&&!id.equals("wiki_forms")?Set.of("filter","search","clear","previous","next"):id.startsWith("dex_")&&!id.equals("dex_forms")?Set.of("info","close","previous","next"):id.equals("rank_captura")?Set.of("total","shiny","legendary"):id.equals("rank_dex")?Set.of("national","special","shiny","forms"):id.equals("rank_derrotados")?Set.of("defeats"):Set.of("future");for(var e:o.getAsJsonObject("buttons").entrySet()){if(!allowed.contains(e.getKey()))throw new IllegalArgumentException("Unknown button action");var b=e.getValue().getAsJsonObject();buttons.put(e.getKey(),new MenuSpec.Button(integer(b.get("slot")),icon(b,true)));}if(!buttons.keySet().equals(allowed))throw new IllegalArgumentException("Missing menu control");var states=new HashMap<String,MenuSpec.Icon>();if(o.has("reward_states"))for(var e:o.getAsJsonObject("reward_states").entrySet()){if(!Set.of("locked","available","claimed").contains(e.getKey()))throw new IllegalArgumentException("Unknown reward state");states.put(e.getKey(),icon(e.getValue().getAsJsonObject(),false));}if(id.startsWith("wiki_")&&!id.equals("wiki_forms")&&integers(o.getAsJsonArray("content_slots")).isEmpty())throw new IllegalArgumentException("Wiki requires content slots");if(id.startsWith("dex_")&&!id.equals("dex_forms")&&integers(o.getAsJsonArray("reward_slots")).isEmpty())throw new IllegalArgumentException("Dex requires reward slots");br.com.shirokaidex.menus.direct.RichText.validate(string(o.get("title")));return new MenuSpec(string(o.get("title")),integer(o.get("rows")),icon(o.getAsJsonObject("background"),false),buttons,integers(o.getAsJsonArray("content_slots")),integers(o.getAsJsonArray("reward_slots")),states,o.has("entry")?icon(o.getAsJsonObject("entry"),false):new MenuSpec.Icon("","%pokemon_name%",List.of("%pokemon_id%","<gray>Visto: %seen%","<gray>Obtido: %owned%","<gray>Capturado: %captured%","%spawns%"),false),o.has("ranking_line")?string(o.get("ranking_line")):"<gray>%position%. <white>%player_name% <gray>— %score%",filterNames(o));}
    private static Map<String,String> filterNames(JsonObject o){var result=new HashMap<>(Map.of("ALL","Todos","SEEN","Vistos","OWNED","Obtidos","UNSEEN","Não vistos","SHINY_SEEN","Shiny vistos"));if(o.has("filter_names"))for(var e:o.getAsJsonObject("filter_names").entrySet()){if(!result.containsKey(e.getKey()))throw new IllegalArgumentException("Unknown wiki filter label");String value=string(e.getValue());if(value.length()>64)throw new IllegalArgumentException("Filter label too long");result.put(e.getKey(),value);}return Map.copyOf(result);}
    private static MenuSpec.Icon icon(JsonObject o,boolean button){keys(o,button?Set.of("slot","item","name","lore","glint"):Set.of("item","name","lore","glint"));br.com.shirokaidex.menus.direct.RichText.validate(string(o.get("name")));for(String line:strings(o.getAsJsonArray("lore")))br.com.shirokaidex.menus.direct.RichText.validate(line);if(o.has("glint")&&(!o.get("glint").isJsonPrimitive()||!o.get("glint").getAsJsonPrimitive().isBoolean()))throw new IllegalArgumentException("Glint must be boolean");return new MenuSpec.Icon(o.has("item")?string(o.get("item")):"",string(o.get("name")),strings(o.getAsJsonArray("lore")),o.has("glint")&&o.get("glint").getAsBoolean());}
    private static void keys(JsonObject o,Set<String> keys){if(!keys.containsAll(o.keySet()))throw new IllegalArgumentException("Unknown menu field");}
    private static String string(JsonElement v){if(v==null||!v.isJsonPrimitive()||!v.getAsJsonPrimitive().isString())throw new IllegalArgumentException("Expected menu text");return v.getAsString();}
    private static int integer(JsonElement v){if(v==null||!v.isJsonPrimitive()||!v.getAsJsonPrimitive().isNumber()||!v.getAsString().matches("[0-9]{1,2}"))throw new IllegalArgumentException("Expected menu integer");return v.getAsInt();}
    private static List<String> strings(JsonArray values){if(values==null)return List.of();var result=new ArrayList<String>();for(var v:values)result.add(string(v));return List.copyOf(result);}
    private static List<Integer> integers(JsonArray values){if(values==null)return List.of();var result=new ArrayList<Integer>();for(var v:values)result.add(integer(v));return List.copyOf(result);}
}
